/// <summary>
/// Constructs the reference identities used to populate the <c>METOrderExtractScreen</c> form.
/// </summary>
public class METOrderExtractScreenProcessor
{
    METOrderExtractScreenTmp            metOrderExtractScreenTmp;
    MEtOrderExtractScreenParameters     metOrderExtractScreenParameters;

    Volume                              totalVolume;

}

Method.Source:
/// <summary>
/// Sets total volume
/// </summary>
/// <param name = "_volume">Volume</param>
/// <returns>Volume</returns>
public Volume parmTotalVolume(Volume _volume = totalVolume)
{
    totalVolume = _volume;
    return totalVolume;
}

/// <summary>
/// set or get <c>MEtOrderExtractScreenParameters</c> class instance.
/// </summary>
/// <param name = "_metOrderExtractScreenParameters"><c>MEtOrderExtractScreenParameters</c> class instance.</param>
/// <returns><c>MEtOrderExtractScreenParameters</c> class instance</returns>
public MEtOrderExtractScreenParameters parmMETOrderExtractScreenParams(
    MEtOrderExtractScreenParameters _metOrderExtractScreenParameters)
{
    MEtOrderExtractScreenParameters = _metOrderExtractScreenParameters;
    return MEtOrderExtractScreenParameters;
}

    /// <summary>
    /// set or get <c>METOrderExtractScreenTmp</c> table instance.
    /// </summary>
    /// <param name = "_metOrderExtractScreenTmp"><c>METOrderExtractScreenTmp</c> table instance</param>
    /// <returns><c>METOrderExtractScreenTmp</c> table instance</returns>
    public METOrderExtractScreenTmp parmMETOrderExtractScreenTmp(
        METOrderExtractScreenTmp _metOrderExtractScreenTmp = metOrderExtractScreenTmp)
    {
        metOrderExtractScreenTmp.linkPhysicalTableInstance(_metOrderExtractScreenTmp);

        return metOrderExtractScreenTmp;
    }

    /// <summary>
    /// Runs the process.
    /// </summary>
    protected void run()
    {
        
        SalesTable                  salesTable;
        SalesLine                   salesLine;
        MetItemSiteSettingsSetup    itemSiteSettings;
        InventDim                   inventDim;

        InventSiteId                site = metOrderExtractScreenParameters.parmSite();
        InventLocationId            warehouse = metOrderExtractScreenParameters.parmWarehouse();
        METRoute                    route = metOrderExtractScreenParameters.parmRoute();
        SalesShippingDateConfirmed  shippingDate = metOrderExtractScreenParameters.parmShippingDateConfirm();
        METFilterCodeone            category = metOrderExtractScreenParameters.parmCategory();

        if (category)
        {
            while select SalesId, InventSiteId from salesTable
                join salesLine
                    where salesLine.SalesId == salesTable.SalesId
                    && salesLine.SalesStatus == SalesStatus::Backorder
                    && salesLine.SalesQty > 0
                join InventSiteId from inventDim
                    where inventDim.inventDimId == salesLine.InventDimId
                    && (!site || inventDim.InventSiteId == site)
                    && (!warehouse || inventDim.InventLocationId == warehouse)
                    && (!route  || salesTable.METRoute == route)
                    && (!shippingDate || salesTable.ShippingDateConfirmed ==  shippingDate)
                    //&& salesTable.SalesStatus == SalesStatus::Backorder
                    && salesTable.DocumentStatus == DocumentStatus::Confirmation
                    && salesTable.METOrderExtractStatus != METOrderExtractStatus::Extracted
                join itemSiteSettings
                    where itemSiteSettings.ItemId == salesLine.ItemId 
                    && itemSiteSettings.InventSiteId == inventDim.InventSiteId
                    && itemSiteSettings.FilterCode1 == category
            {
                this.insertRecord(salesLine, itemSiteSettings);
            }
        }
        else
        {
            while select SalesId, InventSiteId from salesTable
                join salesLine
                    where salesLine.SalesId == salesTable.SalesId
                    && salesLine.SalesStatus == SalesStatus::Backorder
                    && salesLine.SalesQty > 0
                join InventSiteId from inventDim
                    where inventDim.inventDimId == salesLine.InventDimId
                    && (!site || inventDim.InventSiteId == site)
                    && (!warehouse || inventDim.InventLocationId == warehouse)
                    && (!route  || salesTable.METRoute == route)
                    && (!shippingDate || salesTable.ShippingDateConfirmed ==  shippingDate)
                    //&& salesTable.SalesStatus == SalesStatus::Backorder
                    && salesTable.DocumentStatus == DocumentStatus::Confirmation
                    && salesTable.METOrderExtractStatus != METOrderExtractStatus::Extracted
                outer join itemSiteSettings
                    where itemSiteSettings.ItemId == salesLine.ItemId
                    && itemSiteSettings.InventSiteId == inventDim.InventSiteId
            {
                this.insertRecord(salesLine, itemSiteSettings);
            }
        }

        select sum(Volume) from metOrderExtractScreenTmp;
        this.parmTotalVolume(metOrderExtractScreenTmp.Volume);

    }

    /// <summary>
    /// Inserts records into <c>METOrderExtractScreenTmp</c> table.
    /// </summary>
    /// <param name = "_salesLine"><c>SalesLine</c> buffer.</param>
    /// <param name = "_itemSettings"><c>MetItemSiteSettingsSetup</c> buffer</param>
    protected void insertRecord(SalesLine                   _salesLine,
                                MetItemSiteSettingsSetup    _itemSettings)
    {
        select * from metOrderExtractScreenTmp
                    where metOrderExtractScreenTmp.SalesId == _salesLine.SalesId
                && metOrderExtractScreenTmp.FilterCodeOne == _itemSettings.FilterCode1;

        if (!metOrderExtractScreenTmp)
        {
            metOrderExtractScreenTmp.SalesId        =   _salesLine.SalesId;
            metOrderExtractScreenTmp.FilterCodeOne  =   _itemSettings.FilterCode1;
            metOrderExtractScreenTmp.ItemType       =   _itemSettings.ItemType;
            metOrderExtractScreenTmp.Weight         =   _salesLine.displayMETGrossWeight();
            metOrderExtractScreenTmp.Volume         =   _salesLine.displayMETUnitVolume();
            metOrderExtractScreenTmp.METCase        =   _salesLine.displayMETcases();
            metOrderExtractScreenTmp.OSCCode        =   _salesLine.displayMETOSCCode();
            metOrderExtractScreenTmp.BrokenCase     =   _salesLine.displayMETBrokenCase();
            metOrderExtractScreenTmp.insert();
        }
        else
        {
            metOrderExtractScreenTmp.selectForUpdate(true);
            ttsbegin;
            metOrderExtractScreenTmp.Weight         +=   _salesLine.displayMETGrossWeight();
            metOrderExtractScreenTmp.Volume         +=   _salesLine.displayMETUnitVolume();
            metOrderExtractScreenTmp.METCase        +=   _salesLine.displayMETcases();
            metOrderExtractScreenTmp.BrokenCase     +=   _salesLine.displayMETBrokenCase();
            metOrderExtractScreenTmp.update();
            ttscommit;
        }
    
    }

    /// <summary>
    /// Constructs the order extract screen.
    /// </summary>
    /// <param name="_metOrderExtractScreenTmp">
    /// The <c>METOrderExtractScreenTmp</c> instance.
    /// </param>
    /// <param name="_metOrderExtractScreenParameters">
    /// An instance of <c>METOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    /// <returns>METOrderExtractScreenProcessor class instance.</returns>
    public static METOrderExtractScreenProcessor construct(
        METOrderExtractScreenTmp                _metOrderExtractScreenTmp,
        METOrderExtractScreenParameters         _metOrderExtractScreenParameters)
    {
        METOrderExtractScreenProcessor   metOrderExtractScreenProcessor;

        metOrderExtractScreenProcessor = new METOrderExtractScreenProcessor();

        metOrderExtractScreenProcessor.populateOrderExtractScreen(_metOrderExtractScreenTmp, _metOrderExtractScreenParameters);

        return metOrderExtractScreenProcessor;
    }

    /// <summary>
    /// Populates <c>METOrderExtractScreenTmp</c> table for the grid on the order extract screen form.
    /// </summary>
    /// <param name="_metOrderExtractScreenTmp">
    /// The <c>METOrderExtractScreenTmp</c> instance.
    /// </param>
    /// <param name="_metOrderExtractScreenParameters">
    /// An instance of <c>METOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    public void populateOrderExtractScreen(METOrderExtractScreenTmp                _metOrderExtractScreenTmp,
                                            METOrderExtractScreenParameters         _metOrderExtractScreenParameters)
    {
        METOrderExtractScreenProcessor           metOrderExtractScreenProcessor;

        metOrderExtractScreenProcessor = new METOrderExtractScreenProcessor();

        metOrderExtractScreenProcessor.parmMETOrderExtractScreenParams(_metOrderExtractScreenParameters);
        metOrderExtractScreenProcessor.parmMETOrderExtractScreenTmp(_metOrderExtractScreenTmp);
        metOrderExtractScreenProcessor.run();
        this.parmTotalVolume(metOrderExtractScreenProcessor.parmTotalVolume());
    }
